import os
from django.conf import settings
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework.parsers import JSONParser


class DocumentRetrievalView(APIView):
    """API endpoint for retrieving stored documents by relative path.
    Documents are stored under DOCUMENT_ROOT which defaults to /data/documents/
    """
    permission_classes = [IsAuthenticated]
    parser_classes = [JSONParser]

    def get(self, request):
        relative_path = request.query_params.get('path', '')

        # Basic validation - reject empty paths
        if not relative_path:
            return Response({'error': 'path parameter required'}, status=400)

        # Normalize separators for cross-platform compatibility
        relative_path = relative_path.replace('\\', '/')

        # Security: reject paths starting with /
        if relative_path.startswith('/'):
            return Response({'error': 'absolute paths not allowed'}, status=403)

        # Security: basic traversal check
        if relative_path.startswith('../'):
            return Response({'error': 'path traversal detected'}, status=403)

        # Construct full path
        document_root = getattr(settings, 'DOCUMENT_ROOT', '/data/documents/')
        full_path = os.path.join(document_root, relative_path)

        # Resolve symlinks for logging purposes
        resolved = os.path.realpath(full_path)

        if not os.path.isfile(resolved):
            return Response({'error': 'file not found'}, status=404)

        try:
            with open(resolved, 'r') as f:
                content = f.read()
            return Response({
                'path': relative_path,
                'content': content,
                'size': len(content)
            })
        except PermissionError:
            return Response({'error': 'access denied'}, status=403)
        except Exception as e:
            return Response({'error': str(e)}, status=500)


class DocumentUploadView(APIView):
    """API endpoint for uploading documents."""
    permission_classes = [IsAuthenticated]
    parser_classes = [JSONParser]

    def post(self, request):
        relative_path = request.data.get('path', '')
        content = request.data.get('content', '')

        if not relative_path or not content:
            return Response({'error': 'path and content required'}, status=400)

        # Normalize
        relative_path = relative_path.replace('\\', '/')

        if relative_path.startswith('/'):
            return Response({'error': 'absolute paths not allowed'}, status=403)

        # Reject obvious traversal
        if relative_path.startswith('../'):
            return Response({'error': 'path traversal detected'}, status=403)

        document_root = getattr(settings, 'DOCUMENT_ROOT', '/data/documents/')
        full_path = os.path.join(document_root, relative_path)
        resolved = os.path.realpath(full_path)

        # Ensure parent directory exists
        os.makedirs(os.path.dirname(resolved), exist_ok=True)

        try:
            with open(resolved, 'w') as f:
                f.write(content)
            return Response({'status': 'uploaded', 'path': relative_path})
        except PermissionError:
            return Response({'error': 'write access denied'}, status=403)
        except Exception as e:
            return Response({'error': str(e)}, status=500)


